using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class InspectMountainBaseline {public static string Main(){var live=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var road=Object.FindAnyObjectByType<RaceDirector>().road;string temp="Assets/Scenes/MountainCutBaseline.unity";File.Copy("Temp/MountainCutBaseline.unity",temp,true);AssetDatabase.ImportAsset(temp);var baseline=EditorSceneManager.OpenScene(temp,OpenSceneMode.Additive);var old=baseline.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<RaceDirector>()).First().road;old.Initialize();var mesh=baseline.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(m=>m.name=="Ground_CR133 mountain driving surface");var text="mesh="+AssetDatabase.GetAssetPath(mesh.sharedMesh)+"\n";for(int z=150;z>=65;z-=2){var p=new Vector3(990,z>110?152:165,z);var op=old.At(old.Project(p,out _),out _);var np=road.At(road.Project(p,out _),out _);text+=$"z={z} old={op:F3} current={np:F3}\n";}File.WriteAllText("Docs/MountainCut/baseline-grade.txt",text);EditorSceneManager.CloseScene(baseline,true);AssetDatabase.DeleteAsset(temp);return text;}}
